      --bg: #f5f7fb;
      --surface: #ffffff;
      --surface-soft: #f8fafc;
      --text: #111827;
      --muted: #5b6472;
      --border: #d8dee8;
      --danger: #c81e3a;
      --danger-strong: #991b1b;
      --danger-soft: #fff1f2;
      --primary: #2563eb;
      --shadow: 0 24px 70px rgb(15 23 42 / 18%);
      --radius-lg: 28px;
      --radius-md: 18px;
      --focus: #1d4ed8;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-width: 320px;
      margin: 0;
      font-family:
        Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
        "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgb(37 99 235 / 14%), transparent 34rem),
        linear-gradient(135deg, #f8fbff 0%, var(--bg) 48%, #edf3ff 100%);
      line-height: 1.5;
    }

    a,
    button {
      font: inherit;
    }

    button {
      min-height: 44px;
      min-width: 44px;
    }

    :focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    .skip-link {
      position: fixed;
      top: 1rem;
      left: 1rem;
      z-index: 10;
      transform: translateY(-150%);
      border-radius: 999px;
      padding: 0.75rem 1rem;
      color: #ffffff;
      background: #111827;
      text-decoration: none;
      transition: transform 160ms ease;
    }

    .skip-link:focus {
      transform: translateY(0);
    }

    .page {
      display: grid;
      min-height: 100vh;
      place-items: center;
      padding: clamp(1rem, 4vw, 3rem);
    }

    .preview-shell {
      width: min(100%, 1060px);
      overflow: hidden;
      border: 1px solid rgb(148 163 184 / 28%);
      border-radius: var(--radius-lg);
      background: rgb(255 255 255 / 82%);
      box-shadow: var(--shadow);
      backdrop-filter: blur(22px);
    }

    .topbar {
      display: flex;
      flex-wrap: wrap;
      gap: 1rem;
      align-items: center;
      justify-content: space-between;
      padding: 1.25rem clamp(1rem, 3vw, 2rem);
      border-bottom: 1px solid var(--border);
      background: rgb(255 255 255 / 70%);
    }

    .eyebrow {
      margin: 0 0 0.2rem;
      color: var(--primary);
      font-size: 0.78rem;
      font-weight: 800;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.8rem, 4vw, 3rem);
      letter-spacing: -0.05em;
      line-height: 1;
    }

    .status-pill {
      border: 1px solid #bfdbfe;
      border-radius: 999px;
      padding: 0.55rem 0.85rem;
      color: #1e3a8a;
      background: #eff6ff;
      font-size: 0.92rem;
      font-weight: 700;
    }

    .content {
      display: grid;
      grid-template-columns: minmax(0, 1.35fr) minmax(18rem, 0.65fr);
      gap: clamp(1rem, 3vw, 2rem);
      padding: clamp(1rem, 3vw, 2rem);
    }

    .image-card,
    .details-card {
      border: 1px solid var(--border);
      border-radius: var(--radius-md);
      background: var(--surface);
    }

    .image-card {
      overflow: hidden;
    }

    .image-wrap {
      padding: clamp(0.75rem, 2vw, 1.25rem);
      background:
        linear-gradient(45deg, rgb(226 232 240 / 70%) 25%, transparent 25%),
        linear-gradient(-45deg, rgb(226 232 240 / 70%) 25%, transparent 25%),
        linear-gradient(45deg, transparent 75%, rgb(226 232 240 / 70%) 75%),
        linear-gradient(-45deg, transparent 75%, rgb(226 232 240 / 70%) 75%);
      background-position: 0 0, 0 16px, 16px -16px, -16px 0;
      background-size: 32px 32px;
    }

    .preview-image {
      display: block;
      width: 100%;
      height: min(58vh, 560px);
      object-fit: cover;
      border-radius: 14px;
      box-shadow: 0 18px 38px rgb(15 23 42 / 14%);
    }

    .image-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      justify-content: space-between;
      padding: 1rem clamp(1rem, 2vw, 1.25rem);
    }

    .caption {
      margin: 0;
      color: var(--muted);
      font-weight: 650;
    }

    .details-card {
      align-self: start;
      padding: clamp(1rem, 2vw, 1.5rem);
    }

    .details-card h2 {
      margin: 0 0 1rem;
      font-size: 1.15rem;
    }

    .metadata {
      display: grid;
      gap: 1rem;
      margin: 0;
    }

    .metadata div {
      display: grid;
      gap: 0.15rem;
      border-bottom: 1px solid var(--border);
      padding-bottom: 0.8rem;
    }

    .metadata div:last-child {
      border-bottom: 0;
      padding-bottom: 0;
    }

    .metadata dt {
      color: var(--muted);
      font-size: 0.82rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .metadata dd {
      margin: 0;
      font-weight: 750;
    }

    .button {
      display: inline-flex;
      gap: 0.5rem;
      align-items: center;
      justify-content: center;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.72rem 1rem;
      cursor: pointer;
      font-weight: 800;
      text-decoration: none;
      transition:
        background 160ms ease,
        border-color 160ms ease,
        color 160ms ease,
        transform 160ms ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button:active {
      transform: translateY(0);
    }

    .button-danger {
      color: var(--danger);
      border-color: #fecdd3;
      background: var(--danger-soft);
    }

    .button-danger:hover {
      color: #ffffff;
      border-color: var(--danger);
      background: var(--danger);
    }

    .button-secondary {
      color: #1f2937;
      border-color: var(--border);
      background: #ffffff;
    }

    .button-secondary:hover {
      background: var(--surface-soft);
    }

    .button-confirm {
      color: #ffffff;
      background: var(--danger);
    }

    .button-confirm:hover {
      background: var(--danger-strong);
    }

    .delete-dialog {
      width: min(calc(100% - 2rem), 30rem);
      max-height: calc(100vh - 2rem);
      overflow: auto;
      border: 0;
      border-radius: 24px;
      padding: 0;
      color: var(--text);
      background: var(--surface);
      box-shadow: 0 28px 90px rgb(15 23 42 / 34%);
    }

    .delete-dialog::backdrop {
      background: rgb(15 23 42 / 64%);
      backdrop-filter: blur(6px);
    }

    .dialog-content {
      display: grid;
      gap: 1rem;
      padding: clamp(1.25rem, 4vw, 2rem);
    }

    .dialog-icon {
      display: grid;
      width: 3rem;
      height: 3rem;
      place-items: center;
      border-radius: 999px;
      color: var(--danger);
      background: var(--danger-soft);
      font-size: 1.45rem;
      font-weight: 900;
    }

    .delete-dialog h2 {
      margin: 0;
      font-size: clamp(1.35rem, 5vw, 1.75rem);
      letter-spacing: -0.04em;
      line-height: 1.15;
    }

    .delete-dialog p {
      margin: 0;
      color: var(--muted);
    }

    .dialog-actions {
      display: flex;
      flex-wrap: wrap-reverse;
      gap: 0.75rem;
      justify-content: flex-end;
      margin-top: 0.5rem;
    }

    .dialog-actions .button {
      flex: 1 1 9rem;
    }

    .live-status {
      min-height: 1.5rem;
      margin: 1rem 0 0;
      color: #166534;
      font-weight: 750;
    }

    @media (max-width: 760px) {
      .content {
        grid-template-columns: 1fr;
      }

      .image-actions {
        align-items: stretch;
      }

      .image-actions .button {
        width: 100%;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      :root {
        --border: CanvasText;
        --focus: Highlight;
      }

      .preview-shell,
      .image-card,
      .details-card,
      .delete-dialog,
      .button,
      .status-pill {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      .delete-dialog::backdrop {
        background: Canvas;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main">Skip to main content</a>

  <main id="main" class="page">
    <section class="preview-shell" aria-labelledby="page-title">
      <header class="topbar">
        <div>
          <p class="eyebrow">Library preview</p>
          <h1 id="page-title">Mountain sunrise</h1>
        </div>
        <span class="status-pill">Saved to library</span>
      </header>

      <div class="content">
        <article class="image-card" aria-labelledby="image-title">
          <div class="image-wrap">
            <img
              class="preview-image"
              src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&amp;fit=crop&amp;w=1400&amp;q=80"
              alt="Sunrise lighting a mountain lake surrounded by evergreen trees"
            >
          </div>

          <div class="image-actions">
            <p id="image-title" class="caption">mountain-sunrise.jpg</p>
            <button class="button button-danger trigger" type="button" aria-describedby="delete-help">
              Delete image
            </button>
          </div>
        </article>

        <aside class="details-card" aria-labelledby="details-title">
          <h2 id="details-title">Image details</h2>
          <dl class="metadata">
            <div>
              <dt>Collection</dt>
              <dd>Travel inspiration</dd>
            </div>
            <div>
              <dt>Uploaded</dt>
              <dd>Today</dd>
            </div>
            <div>
              <dt>Usage</dt>
              <dd>Hero image draft</dd>
            </div>
          </dl>
          <p id="delete-help" class="live-status" aria-live="polite"></p>
        </aside>
      </div>
    </section>
  </main>

  <dialog class="delete-dialog" id="delete-dialog" aria-labelledby="dialog-title" aria-describedby="dialog-description">
    <form method="dialog" class="dialog-content">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <div>
        <h2 id="dialog-title">Delete this image?</h2>
        <p id="dialog-description">
          This will remove “mountain-sunrise.jpg” from your library. This action cannot be undone.
        </p>
      </div>
      <div class="dialog-actions">
        <button class="button button-secondary" type="submit" value="cancel" autofocus>
          Cancel
        </button>
        <button class="button button-confirm" type="submit" value="delete">
          Delete image
        </button>
      </div>
    </form>
  </dialog>

  <script>
    const dialog = document.querySelector('#delete-dialog');
    const trigger = document.querySelector('.trigger');
    const statusMessage = document.querySelector('#delete-help');

    trigger.addEventListener('click', () => {
      dialog.showModal();
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue === 'delete') {
        statusMessage.textContent = 'Image deleted from your library.';
        trigger.disabled = true;
        trigger.textContent = 'Image deleted';
      }
    });
  </script>
